with flattened_attrs as (select id, customer_id, created_at, ship_to, array_join(array_sort(coupon_codes), ',') as coupons_text, coalesce(attributes['device'], 'unknown') as device_or_default from carts where created_at < '2025-07-01') select customer_id, max(created_at) as ended_at, min(created_at) as started_at, max(created_at) as last_seen, count(distinct device_or_default) as distinct_device_or_defaults from flattened_attrs group by customer_id order by customer_id desc nulls first
